      if (!k) { g.font = `500 ${fs + 1}px ${FONT}`; g.fillStyle = C.muted; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('Нажмите «Ещё тысячу»', pl + pw / 2, (b0 + b1) / 2); }
