        if (!S) return `${base}; средних ещё нет`;
        const log = [...st.log.values()].map(r => `${DISTS[r.d].name} n = ${r.n}: разброс ${fmtV(r.d, r.sd)}, σ/√n ${isFinite(r.se) ? fmtV(r.d, r.se) : '∞'}`).join('; ');
        return `${base}, среднее средних ${fmtV(d, S.m)} (μ = ${fmtV(d, D().mu)}), разброс средних ${fmtV(d, S.sd)} (σ/√n = ${isFinite(se()) ? fmtV(d, se()) : '∞'}), асимметрия средних ${num(S.sk, 2)}; на экране: «${caption(S)}»${log ? `; журнал: ${log}` : ''}`;
